pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _version) public {
        // The reference contract's oracle() returns a non-zero address after deployment.
        // The mutated version returns address(0). This rule should hold for any input.
        // We cannot call any function that requires initialization, so we just assert directly.
        assertTrue(address(c.oracle()) != address(0));
    }
}

